/**
 * Owns Magician state construction, exact live reads and detached player projection.
 * Inputs are original role/history data; outputs retain existing descriptor, day and pair
 * validation. This boundary never exchanges an effect, commits history or closes a frame.
 */
import type {
  MagicianChoice,
  MagicianState,
  MagicianReadState,
} from "@ai-werewolf-arena/game-contract";
import { types } from "node:util";
import { Camp, type RoleComponent } from "../../../../core";
export const MAGICIAN_ROLE = "magician" as const;
export const MAGICIAN_POLICY = "awa_magician_wolf_king_v1" as const;
function field(value: unknown, key: PropertyKey): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && "value" in d ? d.value : undefined;
}
function exact(value: unknown, keys: readonly string[]): boolean {
  if (!value || typeof value !== "object" || types.isProxy(value) || Array.isArray(value))
    return false;
  const descriptors = Object.getOwnPropertyDescriptors(value);
  return (
    Reflect.ownKeys(descriptors).length === keys.length &&
    keys.every((k) => descriptors[k] && "value" in descriptors[k]!)
  );
}
function integer(value: unknown): value is number {
  return (
    typeof value === "number" &&
    Number.isSafeInteger(value) &&
    value > 0 &&
    value < Number.MAX_SAFE_INTEGER
  );
}
function arrayItems(value: unknown): unknown[] | null {
  if (types.isProxy(value) || !Array.isArray(value)) return null;
  const length = field(value, "length");
  if (typeof length !== "number" || !Number.isSafeInteger(length) || length < 0) return null;
  const descriptors = Object.getOwnPropertyDescriptors(value);
  if (Reflect.ownKeys(descriptors).length !== length + 1) return null;
  const result: unknown[] = [];
  for (let i = 0; i < length; i++) {
    const d = descriptors[String(i)];
    if (!d || !("value" in d)) return null;
    result.push(d.value);
  }
  return result;
}
/** Validate without invoking user-owned accessors, iterators or array methods. */
export function getMagicianState(role: RoleComponent | undefined): MagicianReadState | undefined {
  if (field(role, "role") !== MAGICIAN_ROLE || field(role, "camp") !== Camp.Good) return undefined;
  const state = field(field(role, "privateState"), "magician");
  if (!exact(state, ["policy", "firstNight", "deathShotTargetPolicy", "history"])) return undefined;
  const firstNight = field(state, "firstNight");
  if (field(state, "policy") !== MAGICIAN_POLICY || (firstNight !== 1 && firstNight !== 2))
    return undefined;
  const shot = field(state, "deathShotTargetPolicy");
  if (shot !== "original" && shot !== "exchanged") return undefined;
  const history = arrayItems(field(state, "history"));
  if (!history) return undefined;
  let previous = 0;
  const used = new Set<number>();
  for (const entry of history) {
    if (!exact(entry, ["day", "pair"])) return undefined;
    const day = field(entry, "day"),
      rawPair = field(entry, "pair");
    if (!integer(day) || day < firstNight || day <= previous) return undefined;
    previous = day;
    if (rawPair === null) continue;
    const pair = arrayItems(rawPair);
    if (
      !pair ||
      pair.length !== 2 ||
      !integer(pair[0]) ||
      !integer(pair[1]) ||
      pair[0] >= pair[1] ||
      used.has(pair[0]) ||
      used.has(pair[1])
    )
      return undefined;
    used.add(pair[0]);
    used.add(pair[1]);
  }
  return state as MagicianReadState;
}
export function createMagicianState(
  firstNight: 1 | 2,
  deathShotTargetPolicy: "original" | "exchanged" = "original",
): MagicianState {
  return { policy: MAGICIAN_POLICY, firstNight, deathShotTargetPolicy, history: [] };
}
export function projectMagicianState(role: RoleComponent | undefined): MagicianState | undefined {
  const state = getMagicianState(role);
  if (!state) return undefined;
  const history: MagicianChoice[] = [];
  for (const row of arrayItems(field(state, "history"))!) {
    const rawPair = field(row, "pair");
    const values = rawPair === null ? null : arrayItems(rawPair)!;
    history.push({
      day: field(row, "day") as number,
      pair: values ? [values[0] as number, values[1] as number] : null,
    });
  }
  return {
    policy: MAGICIAN_POLICY,
    firstNight: field(state, "firstNight") as 1 | 2,
    deathShotTargetPolicy: field(state, "deathShotTargetPolicy") as "original" | "exchanged",
    history,
  };
}

/**
 * 负责 魔术师 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { roleName, text } from "@ai-werewolf-arena/game-text";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { Role, Camp, WinCondition, Phase } from "../../../../core/domain/identity";
import type { NativeRoleContributions } from "../contracts";
import { MAGICIAN_POLICY, createMagicianState, getMagicianState } from "./state";
import { magicianChoicePending, magicianChoiceTargets } from "./night_frame";
import { MAGICIAN_EXCHANGE_STAGE } from "./night_stages";
const parameters = z.strictObject({
  policy: z.literal(MAGICIAN_POLICY).default(MAGICIAN_POLICY),
  firstNight: z.union([z.literal(1), z.literal(2)]).default(1),
  deathShotTargetPolicy: z.enum(["original", "exchanged"]).default("original"),
});
export const MAGICIAN_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.Magician,
    camp: Camp.Good,
    goodSide: "god",
    maxCount: 1,
    supportedWinConditions: [WinCondition.SlaughterSide],
    supportedBoardRoles: [
      Role.WolfSorcerer,
      Role.Psychic,
      Role.Trickster,
      Role.OrderPrince,
      Role.Wolf,
      Role.WolfKing,
      Role.Villager,
      Role.Seer,
      Role.Witch,
      Role.Hunter,
      Role.Magician,
    ],
    label: roleName("magician"),
    skillBrief: text("zh-CN", "role.magician.brief"),
  },
  runtime: {
    init: (role, ctx) => {
      const value = parameters.parse(ctx.boardConfig?.magician ?? {});
      role.privateState.magician = createMagicianState(
        value.firstNight,
        value.deathShotTargetPolicy,
      );
    },
    configuration: {
      schema: parameters,
      defaults: parameters.parse({}),
      apply: (config, value) => ({ ...config, magician: parameters.parse(value) }),
      serialize: (config) => parameters.parse(config.magician ?? {}),
    },
    toolSpecs: [
      {
        name: "swap_targets",
        parameters: {
          type: "object",
          properties: {
            first_id: { type: ["integer", "null"], minimum: 1 },
            second_id: { type: ["integer", "null"], minimum: 1 },
            abstain: { type: "boolean" },
          },
          required: ["first_id", "second_id", "abstain"],
          additionalProperties: false,
        },
        argHint:
          'swap_targets args: {"first_id":number|null,"second_id":number|null,"abstain":true|false}',
        userPromptHintKey: "action.swap_targets.hint",
      },
    ],
    stageDirectives: [
      {
        match: (tools) => tools.length === 1 && tools[0] === "swap_targets",
        messageKey: "action.swap_targets.directive",
        text: text("zh-CN", "action.swap_targets.directive"),
      },
    ],
    validationRules: {
      swap_targets: ({ world, role, actorId, day, phase, toolCall }) => {
        if (
          !getMagicianState(role) ||
          day === undefined ||
          phase !== Phase.Night ||
          toolCall.name !== "swap_targets" ||
          !magicianChoicePending(world, actorId, day)
        )
          return { code: RuleError.MagicianUnavailable };
        const { first_id, second_id, abstain } = toolCall.args;
        if (abstain)
          return first_id === null && second_id === null
            ? null
            : { code: RuleError.MagicianTarget };
        const targets = magicianChoiceTargets(world, day);
        return first_id !== null &&
          second_id !== null &&
          first_id !== second_id &&
          targets.includes(first_id) &&
          targets.includes(second_id)
          ? null
          : { code: RuleError.MagicianTarget };
      },
    },
    nightStages: [MAGICIAN_EXCHANGE_STAGE],
    baselineAction: (role, request, _pick, _pickCamp, _locale, world) => {
      if (!request.allowedTools.includes("swap_targets") || !world || !getMagicianState(role))
        return null;
      const targets = magicianChoiceTargets(world, request.context.day);
      return targets.length >= 2
        ? {
            name: "swap_targets",
            args: { first_id: targets[0]!, second_id: targets[1]!, abstain: false },
          }
        : { name: "swap_targets", args: { first_id: null, second_id: null, abstain: true } };
    },
  },
  presentation: nativeRolePresentation("magician"),
};

/**
 * Owns Magician night exchange bindings and target-remapping receipts. Inputs are original
 * player bodies and the paired choice; outputs preserve current mappings, cancellation and
 * close/abort behavior. It never lets a stale source redirect a later native action using the
 * old exchange.
 */
import type { MagicianReadState } from "@ai-werewolf-arena/game-contract";
import { isWolfSorcererBoard, resolveWolfSorcererNightTarget } from "../wolf_sorcerer/night_frame";
import { matchingExchangePairs } from "../trickster/exile_mapping";
import { types } from "node:util";
import { COMPONENT, type RoleComponent, type World } from "../../../../core";
import {
  aliveLifeDescriptor,
  aliveLifeVersion,
  type AliveComponent,
} from "../../../../core/domain/components/alive";
import type { NightLifeScope } from "../../../../core/domain/night_effects";
import { getMagicianState, projectMagicianState, MAGICIAN_ROLE } from "./state";

interface OriginalPlayer {
  id: number;
  role: RoleComponent;
  roleName: RoleComponent["role"];
  camp: RoleComponent["camp"];
  privateState: RoleComponent["privateState"];
  identity: unknown;
  seat: number;
  name: string;
  sessionId: string;
  life: AliveComponent;
  version: number;
}
interface ExchangeNight {
  day: number;
  closed: boolean;
  committed: boolean;
  pair: readonly [number, number] | null;
  targets: ReadonlyMap<number, OriginalPlayer>;
}
interface Board {
  actorId: number;
  state: MagicianReadState;
  expectedState: string;
  players: ReadonlyMap<number, OriginalPlayer>;
  night: ExchangeNight | null;
}
const boards = new WeakMap<World, Board>();
function stateIdentity(role: RoleComponent): string {
  const view = projectMagicianState(role);
  if (!view) throw new Error("magician_original_state_revoked");
  return JSON.stringify(view);
}
function ownData(value: unknown, key: PropertyKey): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && "value" in d ? d.value : undefined;
}
function originalPlayer(world: World, p: OriginalPlayer): boolean {
  if (
    world.getComponent(p.id, COMPONENT.Role) !== p.role ||
    ownData(p.role, "role") !== p.roleName ||
    ownData(p.role, "camp") !== p.camp ||
    ownData(p.role, "privateState") !== p.privateState ||
    world.getComponent(p.id, COMPONENT.Identity) !== p.identity ||
    ownData(p.identity, "id") !== p.id ||
    ownData(p.identity, "seat") !== p.seat ||
    ownData(p.identity, "name") !== p.name ||
    ownData(p.identity, "sessionId") !== p.sessionId ||
    world.getComponent(p.id, COMPONENT.Alive) !== p.life
  )
    return false;
  const expected = aliveLifeDescriptor(p.life);
  const current = Object.getOwnPropertyDescriptor(p.life, "alive");
  if (
    !expected ||
    !current ||
    current.get !== expected.get ||
    current.set !== expected.set ||
    current.enumerable !== expected.enumerable ||
    current.configurable !== expected.configurable
  )
    return false;
  const version = aliveLifeVersion(p.life);
  // A committed exchange survives one ordinary death, never revival or another life.
  return p.life.alive ? version === p.version : version === p.version + 1;
}
function requireBoard(world: World): Board {
  const b = boards.get(world);
  if (!b) throw new Error("magician_board_missing");
  const ids = world.entityIds();
  if (
    ids.length !== b.players.size ||
    ids.some((id) => !b.players.has(id)) ||
    [...b.players.values()].some((p) => !originalPlayer(world, p))
  )
    throw new Error("magician_original_state_revoked");
  const actor = b.players.get(b.actorId)!;
  if (getMagicianState(actor.role) !== b.state || stateIdentity(actor.role) !== b.expectedState)
    throw new Error("magician_original_state_revoked");
  return b;
}
export function installMagicianBoard(world: World): void {
  if (boards.has(world)) throw new Error("magician_board_already_installed");
  const players = new Map<number, OriginalPlayer>();
  const seats = new Set<number>();
  let actorId: number | null = null;
  let state: MagicianReadState | undefined;
  for (const id of world.entityIds()) {
    const role = world.getComponent(id, COMPONENT.Role);
    const life = world.getComponent(id, COMPONENT.Alive);
    const version = life && aliveLifeVersion(life);
    if (!role || !life || types.isProxy(life) || version === undefined)
      throw new Error("magician_original_roster_invalid");
    const expected = aliveLifeDescriptor(life);
    const descriptor = Object.getOwnPropertyDescriptor(life, "alive");
    if (
      !expected ||
      !descriptor ||
      expected.get !== descriptor.get ||
      expected.set !== descriptor.set ||
      expected.enumerable !== descriptor.enumerable ||
      expected.configurable !== descriptor.configurable ||
      !life.alive
    )
      throw new Error("magician_original_roster_invalid");
    if (
      ownData(role, "role") === undefined ||
      ownData(role, "camp") === undefined ||
      ownData(role, "privateState") === undefined
    )
      throw new Error("magician_original_roster_invalid");
    const identity = world.getComponent(id, COMPONENT.Identity);
    const seat = ownData(identity, "seat"),
      name = ownData(identity, "name"),
      sessionId = ownData(identity, "sessionId");
    if (
      ownData(identity, "id") !== id ||
      typeof seat !== "number" ||
      !Number.isSafeInteger(seat) ||
      seat <= 0 ||
      seats.has(seat) ||
      typeof name !== "string" ||
      typeof sessionId !== "string"
    )
      throw new Error("magician_original_roster_invalid");
    seats.add(seat);
    players.set(id, {
      id,
      role,
      roleName: role.role,
      camp: role.camp,
      privateState: role.privateState,
      identity,
      seat,
      name,
      sessionId,
      life,
      version,
    });
    if (String(role.role) === MAGICIAN_ROLE) {
      if (actorId !== null) throw new Error("magician_original_roster_invalid");
      actorId = id;
      state = getMagicianState(role);
    }
  }
  if (actorId === null || !state || state.history.length !== 0)
    throw new Error("magician_original_roster_invalid");
  boards.set(world, {
    actorId,
    state,
    expectedState: stateIdentity(players.get(actorId)!.role),
    players,
    night: null,
  });
}
export function isMagicianBoard(world: World): boolean {
  if (!boards.has(world)) return false;
  requireBoard(world);
  return true;
}
export function beginMagicianNight(world: World, day: number): number | null {
  const b = requireBoard(world);
  if (
    !Number.isSafeInteger(day) ||
    day <= 0 ||
    day >= Number.MAX_SAFE_INTEGER ||
    (!b.night && day !== 1) ||
    (b.night && (!b.night.closed || day !== b.night.day + 1))
  )
    throw new Error("magician_night_invalid");
  const used = new Set<number>();
  for (const choice of projectMagicianState(b.players.get(b.actorId)!.role)!.history)
    if (choice.pair) {
      used.add(choice.pair[0]);
      used.add(choice.pair[1]);
    }
  const targets = new Map([...b.players].filter(([id, p]) => p.life.alive && !used.has(id)));
  const eligible =
    day >= b.state.firstNight && b.players.get(b.actorId)!.life.alive && targets.size >= 2;
  b.night = { day, closed: false, committed: !eligible, pair: null, targets };
  return eligible ? b.actorId : null;
}
export function magicianChoiceTargets(world: World, day: number): number[] {
  const b = requireBoard(world),
    n = b.night;
  if (!n || n.day !== day || n.closed || n.committed) return [];
  return [...n.targets.values()].filter((p) => p.life.alive).map((p) => p.id);
}
export function commitMagicianExchange(
  world: World,
  actorId: number,
  day: number,
  pair: readonly [number, number] | null,
): void {
  const b = requireBoard(world),
    n = b.night;
  if (
    !n ||
    n.day !== day ||
    n.closed ||
    n.committed ||
    b.actorId !== actorId ||
    !b.players.get(actorId)!.life.alive
  )
    throw new Error("magician_choice_scope_invalid");
  let chosen: [number, number] | null = null;
  if (pair !== null) {
    if (types.isProxy(pair) || !Array.isArray(pair))
      throw new Error("magician_choice_target_invalid");
    const descriptors: Record<string, PropertyDescriptor> = Object.getOwnPropertyDescriptors(
      pair as object,
    );
    const a = descriptors["0"]?.value,
      z = descriptors["1"]?.value;
    if (
      Reflect.ownKeys(descriptors).length !== 3 ||
      descriptors.length?.value !== 2 ||
      !Number.isSafeInteger(a) ||
      !Number.isSafeInteger(z) ||
      a <= 0 ||
      z <= 0
    )
      throw new Error("magician_choice_target_invalid");
    if (a === z || !n.targets.get(a)?.life.alive || !n.targets.get(z)?.life.alive)
      throw new Error("magician_choice_target_invalid");
    chosen = a < z ? [a, z] : [z, a];
  }
  Object.defineProperty(b.state.history, String(b.state.history.length), {
    value: { day, pair: chosen },
    writable: true,
    enumerable: true,
    configurable: true,
  });
  b.expectedState = stateIdentity(b.players.get(actorId)!.role);
  n.pair = chosen && Object.freeze([chosen[0], chosen[1]] as [number, number]);
  n.committed = true;
}
export interface MagicianResolvedTarget {
  readonly requestedId: number;
  readonly effectiveId: number;
  readonly scope: NightLifeScope;
  readonly isCurrent: () => boolean;
}
export function resolveMagicianNightTarget(
  world: World,
  day: number,
  requestedId: number,
  kind: "night_action" | "death_shot" = "night_action",
): MagicianResolvedTarget {
  const b = requireBoard(world),
    n = b.night;
  if (!n || n.day !== day || n.closed || !n.committed) throw new Error("magician_night_unsettled");
  const original = b.players.get(requestedId);
  if (!original || !original.life.alive) throw new Error("magician_target_invalid");
  const originalShot = kind === "death_shot" && b.state.deathShotTargetPolicy === "original";
  // A second swap exchanges occupants of positions; resolve W(raw) before M.
  // Intermediate occupants may already be dead in a night death-shot chain.
  const second = isWolfSorcererBoard(world)
    ? resolveWolfSorcererNightTarget(
        world,
        day,
        requestedId,
        originalShot ? "original" : "intermediate",
      )
    : null;
  const intermediateId = second?.effectiveId ?? requestedId;
  const pair = originalShot ? null : n.pair;
  const effectiveId = pair
    ? intermediateId === pair[0]
      ? pair[1]
      : intermediateId === pair[1]
        ? pair[0]
        : intermediateId
    : intermediateId;
  const effective = b.players.get(effectiveId)!;
  if (kind === "night_action" && !effective.life.alive) throw new Error("magician_target_invalid");
  const nightPair = n.pair;
  const requestedVersion = aliveLifeVersion(original.life)!;
  const scope: NightLifeScope = Object.freeze({
    id: effectiveId,
    life: effective.life,
    version: aliveLifeVersion(effective.life)!,
  });
  return Object.freeze({
    requestedId,
    effectiveId,
    scope,
    isCurrent: () => {
      try {
        return (
          requireBoard(world) === b &&
          b.night === n &&
          n.pair === nightPair &&
          (!second || second.isCurrent()) &&
          !n.closed &&
          originalPlayer(world, original) &&
          originalPlayer(world, effective) &&
          original.life.alive &&
          aliveLifeVersion(original.life) === requestedVersion &&
          aliveLifeVersion(effective.life) === scope.version
        );
      } catch {
        return false;
      }
    },
  });
}
export function closeMagicianNight(world: World, day: number): void {
  const b = requireBoard(world),
    n = b.night;
  if (!n || n.day !== day || n.closed || !n.committed) throw new Error("magician_night_unsettled");
  n.closed = true;
}

export function assertMagicianRosterCurrent(world: World): void {
  requireBoard(world);
}
export function magicianChoicePending(world: World, actorId: number, day: number): boolean {
  const b = requireBoard(world),
    n = b.night;
  return (
    b.actorId === actorId &&
    !!n &&
    n.day === day &&
    !n.closed &&
    !n.committed &&
    b.players.get(actorId)!.life.alive
  );
}

/** Cleanup only: never validates or repairs a revoked roster, and never records a choice. */
export function abortMagicianNight(world: World): void {
  const n = boards.get(world)?.night;
  if (n) n.closed = true;
}

/** Cancel only the current matching pair; committed number consumption stays in history. */
export function cancelMagicianExchangeIfMatching(
  world: World,
  day: number,
  pair: readonly [number, number],
): boolean {
  const b = requireBoard(world),
    n = b.night;
  if (!n || n.day !== day || n.closed || !n.committed) throw new Error("magician_night_unsettled");
  if (!n.pair || !matchingExchangePairs(n.pair, pair)) return false;
  n.pair = null;
  return true;
}

/**
 * Runs the Magician exchange request before remapped night abilities. Inputs are the installed
 * night frame and validated pair selection; outputs are the original exchange event and
 * authority commit. The stage never applies target mapping eagerly through a prompt; the frame
 * supplies the later receipt.
 */
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Phase } from "../../../../core/domain/identity";
import type { NightStageHandler } from "../../stages/night/contracts";
import { getMagicianState } from "./state";
import {
  assertMagicianRosterCurrent,
  beginMagicianNight,
  commitMagicianExchange,
  magicianChoiceTargets,
} from "./night_frame";
/** Runs from the configured role set, including after the magician's death. */
export const MAGICIAN_EXCHANGE_STAGE: NightStageHandler = {
  id: "magician_exchange",
  priority: 80,
  async execute(ctx) {
    const day = ctx.currentDay(),
      actorId = beginMagicianNight(ctx.world, day);
    if (actorId === null) return;
    const role = ctx.world.getComponent(actorId, COMPONENT.Role);
    if (!getMagicianState(role)) throw new Error("magician_actor_invalid");
    const request = ctx.makeRequest(actorId, ["swap_targets"], {
      stage: "magician_exchange",
      requiresAction: true,
      action_failure_policy: "error",
      allow_fallback: false,
      swap_candidates: magicianChoiceTargets(ctx.world, day),
    });
    assertMagicianRosterCurrent(ctx.world);
    const action = await ctx.actionProvider.getAction(request);
    assertMagicianRosterCurrent(ctx.world);
    if (!ctx.isCurrent() || ctx.currentDay() !== day) throw new Error("magician_exchange_stale");
    if (action?.name !== "swap_targets") throw new Error("magician_exchange_action_missing");
    const validated = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
      phase: Phase.Night,
      day,
    });
    assertMagicianRosterCurrent(ctx.world);
    if (!ctx.isCurrent() || ctx.currentDay() !== day) throw new Error("magician_exchange_stale");
    if (!validated.ok || validated.sanitizedCall?.name !== "swap_targets")
      throw new Error("magician_exchange_action_invalid");
    const args = validated.sanitizedCall.args;
    const pair: [number, number] | null = args.abstain ? null : [args.first_id!, args.second_id!];
    commitMagicianExchange(ctx.world, actorId, day, pair);
    ctx.events.push({
      timestamp: Date.now(),
      type: "magician_exchange_committed",
      payload: {
        actorId,
        day,
        pair: pair && [Math.min(pair[0], pair[1]), Math.max(pair[0], pair[1])],
      },
      audience: Object.freeze([actorId]),
    });
  },
};

